        public static <T> T copy(T from, T reuse, Kryo kryo, TypeSerializer<T> serializer) {
            try {
                return kryo.copy(from);
            } catch (KryoException ke) {
                try {
                    byte[] byteArray = serializeToByteArray(serializer, from);
                    return deserializeFromByteArray(serializer, reuse, byteArray);
                } catch (IOException ioe) {
                    throw new RuntimeException("Could not copy object by serializing/deserializing" + " it.", ioe);
                }
            }
        }

        private static <T> byte[] serializeToByteArray(TypeSerializer<T> serializer, T object) throws IOException {
            return new byte[0];
        }

        private static <T> T deserializeFromByteArray(TypeSerializer<T> serializer, T reuse, byte[] bytes) throws IOException {
            return reuse;
        }
    }
}

