package org.apache.flink.api.java.typeutils.runtime.kryo;

import com.esotericsoftware.kryo.Kryo;
import com.esotericsoftware.kryo.io.Input;
import com.esotericsoftware.kryo.util.ObjectMap;
import org.junit.jupiter.api.Test;

import java.io.ByteArrayInputStream;
import java.io.ObjectInputStream;

public class JavaSerializerread_ObjectMapputFikaTest {

    @Test
    public void testReadInvokesObjectMapPut() throws Exception {
        Kryo kryo = new Kryo();
        Input input = new Input(new ByteArrayInputStream(new byte[0]));

        // Create a custom JavaSerializer instance
        JavaSerializer<Object> serializer = new JavaSerializer<>();

        // First read should create ObjectInputStream and put it in graph context
        try {
            serializer.read(kryo, input, Object.class);
        } catch (Exception e) {
            // Expected - no serialized data in input
        }

        // Clear graph context to ensure fresh state
        kryo.getGraphContext().clear();

        // Create new input with serialized data
        byte[] serializedData = createSerializedObject();
        input = new Input(new ByteArrayInputStream(serializedData));

        // This read should invoke ObjectMap.put when creating ObjectInputStream
        try {
            serializer.read(kryo, input, Object.class);
        } catch (Exception e) {
            // Expected - we only care about reaching the put method
        }
    }

    private byte[] createSerializedObject() throws Exception {
        java.io.ByteArrayOutputStream baos = new java.io.ByteArrayOutputStream();
        java.io.ObjectOutputStream oos = new java.io.ObjectOutputStream(baos);
        oos.writeObject("testObject");
        oos.close();
        return baos.toByteArray();
    }

    // Inner class matching the serializer structure from the provided code
    @SuppressWarnings({"unchecked", "rawtypes"})
    private static class JavaSerializer<T> {
        public T read(Kryo kryo, Input input, Class aClass) {
            try {
                ObjectMap graphContext = kryo.getGraphContext();
                ObjectInputStream objectStream = ((ObjectInputStream) (graphContext.get(this)));
                if (objectStream == null) {
                    objectStream = new InstantiationUtil.ClassLoaderObjectInputStream(input, kryo.getClassLoader());
                    graphContext.put(this, objectStream);
                }
                return ((T) (objectStream.readObject()));
            } catch (Exception ex) {
                throw new com.esotericsoftware.kryo.KryoException("Error during Java deserialization.", ex);
            }
        }
    }

    // Supporting class to match the original code structure
    private static class InstantiationUtil {
        static class ClassLoaderObjectInputStream extends ObjectInputStream {
            public ClassLoaderObjectInputStream(Input input, ClassLoader classLoader) throws Exception {
                super(new java.io.ByteArrayInputStream(input.getBuffer()));
            }
        }
    }
}

