        // Create a minimal tar file in memory
        byte[] tarData = createMinimalTarData();
        File tarFile = new File(tempDir, "test.tar");
        Files.write(tarFile.toPath(), tarData);

        // Create target directory
        File targetDir = new File(tempDir, "extract");
        targetDir.mkdirs();

        // Invoke the method under test
        extractTarFileUsingJava(tarFile.getAbsolutePath(), targetDir.getAbsolutePath(), false);
    }

    private static byte[] createMinimalTarData() {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        DataOutputStream dos = new DataOutputStream(baos);

        try {
            // Tar header for empty file "test.txt"
            String fileName = "test.txt";

            // File name (100 bytes)
            byte[] nameBytes = fileName.getBytes("UTF-8");
            dos.write(nameBytes);
            for (int i = nameBytes.length; i < 100; i++) {
                dos.writeByte(0);
            }

            // File mode (8 bytes)
            writeOctal(dos, "0000644", 8);

            // Owner ID (8 bytes)
            writeOctal(dos, "0000000", 8);

            // Group ID (8 bytes)
            writeOctal(dos, "0000000", 8);

            // File size (12 bytes) - empty file
            writeOctal(dos, "00000000000", 12);

            // Modification time (12 bytes)
            writeOctal(dos, "00000000000", 12);

            // Checksum placeholder (8 bytes) - will calculate later
            byte[] checksumPlaceholder = new byte[8];
            dos.write(checksumPlaceholder);

            // Type flag (1 byte) - regular file
            dos.writeByte('0');

            // Link name (100 bytes)
            byte[] linkBytes = new byte[100];
            dos.write(linkBytes);

            // Magic (6 bytes)
            dos.write("ustar ".getBytes("UTF-8"));

            // Version (2 bytes)
            dos.writeByte('0');
            dos.writeByte('0');

            // Owner name (32 bytes)
            byte[] ownerBytes = new byte[32];
            dos.write(ownerBytes);

            // Group name (32 bytes)
            byte[] groupBytes = new byte[32];
            dos.write(groupBytes);

            // Device major (8 bytes)
            byte[] majorBytes = new byte[8];
            dos.write(majorBytes);

            // Device minor (8 bytes)
            byte[] minorBytes = new byte[8];
            dos.write(minorBytes);

            // Prefix (155 bytes)
            byte[] prefixBytes = new byte[155];
            dos.write(prefixBytes);

            // Padding (12 bytes)
            byte[] paddingBytes = new byte[12];
            dos.write(paddingBytes);

            // File content (0 bytes for empty file)

            // End of file - two empty blocks
            byte[] endBlocks = new byte[1024];
            dos.write(endBlocks);

            dos.flush();

        } catch (IOException e) {
            throw new RuntimeException(e);
        }

        return baos.toByteArray();
    }

    private static void writeOctal(DataOutputStream dos, String value, int length) throws IOException {
        byte[] bytes = value.getBytes("UTF-8");
        dos.write(bytes);
        for (int i = bytes.length; i < length; i++) {
            dos.writeByte(' ');
        }
    }

