    if (contextMark.isPresent() && (((((problem == null) || (!problemMark.isPresent())) || contextMark.get().getName().equals(problemMark.get().getName())) || (contextMark.get().getLine() != problemMark.get().getLine())) || (contextMark.get().getColumn() != problemMark.get().getColumn()))) {
        lines.append(hiddenSensitiveDataInMark(contextMark.get()));
        lines.append("\n");
