package org.apache.flink.configuration;

import org.junit.jupiter.api.Test;
import org.snakeyaml.engine.v2.exceptions.MarkedYamlEngineException;
import org.snakeyaml.engine.v2.exceptions.YamlEngineException;
import org.snakeyaml.engine.v2.nodes.Mark;
import java.util.Optional;

class YamlParserUtilswrapExceptionToHiddenSensitiveData_YamlEngineExceptionsetStackTraceFikaTest {

    @Test
    void testWrapExceptionToHiddenSensitiveData() throws Exception {
        MarkedYamlEngineException exception = new MarkedYamlEngineException(
            "Test context",
            Optional.of(new Mark("test", 1, 1, 0, new int[0], 0)),
            Optional.of(new Mark("test", 2, 1, 0, new int[0], 0)),
            "Test problem",
            null
        );

        // Invoke the private method via reflection
        java.lang.reflect.Method method = getClass().getDeclaringClass()
            .getDeclaredMethod("wrapExceptionToHiddenSensitiveData", MarkedYamlEngineException.class);
        method.setAccessible(true);

        // This will execute the method and reach yamlException.setStackTrace()
        method.invoke(null, exception);
    }
}

