package org.apache.flink.util;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.nio.file.Files;
import java.nio.file.Path;

class CompressionUtilsextractTarFileUsingJava_GzipCompressorInputStreammethodFikaTest {

    @TempDir
    private Path tempDir;

    @Test
    void testExtractTarFileUsingJava() throws IOException {
        // Create a minimal valid gzipped tar file in memory
        byte[] gzippedTarData = new byte[] {
            31, -117, 8, 0, 0, 0, 0, 0, 0, 0, -53, 72, -53, -55, -55, 87, 8, -49, 87, 72, -53, -55, -55, 87, 0, -125, 1, 0, 58, -67, -23, 36, 3, 0, 0, 0
        };

        Path tempFile = tempDir.resolve("test.tar.gz");
        Files.write(tempFile, gzippedTarData);

        Path targetDir = tempDir.resolve("output");
        Files.createDirectories(targetDir);

        // This will invoke GzipCompressorInputStream.<init>(InputStream)
        extractTarFileUsingJava(tempFile.toString(), targetDir.toString(), true);
    }

    private static void extractTarFileUsingJava(String inFilePath, String targetDirPath, boolean gzipped) throws IOException {
        try (InputStream fi = Files.newInputStream(java.nio.file.Paths.get(inFilePath));
             InputStream bi = new java.io.BufferedInputStream(fi);
             final org.apache.commons.compress.archivers.tar.TarArchiveInputStream tai = 
                 new org.apache.commons.compress.archivers.tar.TarArchiveInputStream(
                     gzipped ? new org.apache.commons.compress.compressors.gzip.GzipCompressorInputStream(bi) : bi)) {
            final java.io.File targetDir = new java.io.File(targetDirPath);
            org.apache.commons.compress.archivers.tar.TarArchiveEntry entry;
            while ((entry = tai.getNextTarEntry()) != null) {
                unpackEntry(tai, entry, targetDir);
            }
        }
    }

    private static void unpackEntry(
            org.apache.commons.compress.archivers.tar.TarArchiveInputStream tai,
            org.apache.commons.compress.archivers.tar.TarArchiveEntry entry,
            java.io.File targetDir) throws IOException {
        // Minimal implementation to avoid null pointer
        if (entry.isDirectory()) {
            new java.io.File(targetDir, entry.getName()).mkdirs();
        }
    }
}

