            if ((level == ExecutionConfig.ClosureCleanerLevel.RECURSIVE) && needsRecursion(f, fieldObject)) {
                if (LOG.isDebugEnabled()) {
                    LOG.debug("Dig to clean the {}", fieldObject.getClass().getName());
