@Override
public void read(DataInputView in) throws IOException {
    synchronized(this.confData) {
        final int numberOfProperties = in.readInt();
        for (int i = 0; i < numberOfProperties; i++) {
            String key = StringValue.readString(in);
            Object value;
            byte type = in.readByte();
            switch (type) {
                case TYPE_STRING :
                    value = StringValue.readString(in);
                    break;
                case TYPE_INT :
                    value = in.readInt();
                    break;
                case TYPE_LONG :
                    value = in.readLong();
                    break;
                case TYPE_FLOAT :
                    value = in.readFloat();
                    break;
                case TYPE_DOUBLE :
                    value = in.readDouble();
                    break;
                case TYPE_BOOLEAN :
                    value = in.readBoolean();
                    break;
                case TYPE_BYTES :
                    byte[] bytes = new byte[in.readInt()];
                    in.readFully(bytes);
                    value = bytes;
                    break;
                default :
                    throw new IOException(String.format("Unrecognized type: %s. This method is deprecated and" + " might not work for all supported types.", type));
            }
            this.confData.put(key, value);
        }
    }
}

// --------------------------------------------------------------------------------------------
<T> void setValueInternal(String key, T value, boolean canBePrefixMap) {
    if (key == null) {
        throw new NullPointerException("Key must not be null.");
    }
    if (value == null) {
        throw new NullPointerException("Value must not be null.");
    }
    synchronized(this.confData) {
        if (canBePrefixMap) {
            removePrefixMap(this.confData, key);
        }
        this.confData.put(key, value);
    }
}

@Override
public void write(final DataOutputView out) throws IOException {
    synchronized(this.confData) {
        out.writeInt(this.confData.size());
        for (Map.Entry<String, Object> entry : this.confData.entrySet()) {
            String key = entry.getKey();
            Object val = entry.getValue();
            StringValue.writeString(key, out);
            Class<?> clazz = val.getClass();
            if (clazz == String.class) {
                out.write(TYPE_STRING);
                StringValue.writeString(((String) (val)), out);
            } else if (clazz == Integer.class) {
                out.write(TYPE_INT);
                out.writeInt(((Integer) (val)));
            } else if (clazz == Long.class) {
                out.write(TYPE_LONG);
                out.writeLong(((Long) (val)));
            } else if (clazz == Float.class) {
                out.write(TYPE_FLOAT);
                out.writeFloat(((Float) (val)));
            } else if (clazz == Double.class) {
                out.write(TYPE_DOUBLE);
                out.writeDouble(((Double) (val)));
            } else if (clazz == byte[].class) {
                out.write(TYPE_BYTES);
                byte[] bytes = ((byte[]) (val));
                out.writeInt(bytes.length);
                out.write(bytes);
            } else if (clazz == Boolean.class) {
                out.write(TYPE_BOOLEAN);
                out.writeBoolean(((Boolean) (val)));
            } else {
                throw new IllegalArgumentException("Unrecognized type. This method is deprecated and might not work" + " for all supported types.");
            }
        }
    }
}

