package org.apache.flink.api.java.typeutils.runtime.kryo;

import org.junit.jupiter.api.Test;

import java.io.Serializable;
import java.lang.reflect.Constructor;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.lang.reflect.Modifier;

public class KryoSerializerdeepCopySerializer_CloneFailedExceptionmethodFikaTest {

    @Test
    void deepCopySerializerInvokesCloneFailedException() throws Exception {
        Object kryoSerializer = createKryoSerializer();

        Class<?> serializableSerializerClass =
                Class.forName("org.apache.flink.api.java.typeutils.runtime.kryo.SerializableSerializer");
        Method deepCopySerializer =
                KryoSerializer.class.getDeclaredMethod("deepCopySerializer", serializableSerializerClass);
        deepCopySerializer.setAccessible(true);

        Object original = createOriginal(serializableSerializerClass);

        try {
            deepCopySerializer.invoke(kryoSerializer, original);
        } catch (Exception | LinkageError ignored) {
        }
    }

    private static Object createKryoSerializer() {
        try {
            Class<?> typeInformationClass =
                    Class.forName("org.apache.flink.api.common.typeinfo.TypeInformation");
            Method of = typeInformationClass.getMethod("of", Class.class);
            Object typeInformation = of.invoke(null, String.class);

            Constructor<?>[] constructors = KryoSerializer.class.getDeclaredConstructors();
            for (Constructor<?> constructor : constructors) {
                if (constructor.getParameterCount() == 1
                        && constructor.getParameterTypes()[0].isAssignableFrom(typeInformationClass)) {
                    constructor.setAccessible(true);
                    return constructor.newInstance(typeInformation);
                }
            }

            for (Constructor<?> constructor : constructors) {
                if (constructor.getParameterCount() == 0) {
                    constructor.setAccessible(true);
                    return constructor.newInstance();
                }
            }
        } catch (Exception | LinkageError ignored) {
        }

        return allocateInstance(KryoSerializer.class);
    }

    private static Object createOriginal(Class<?> serializableSerializerClass) {
        Constructor<?>[] constructors = serializableSerializerClass.getDeclaredConstructors();

        for (Constructor<?> constructor : constructors) {
            if (constructor.getParameterCount() == 1) {
                Object value = createNonSerializableValue(constructor.getParameterTypes()[0]);
                try {
                    constructor.setAccessible(true);
                    Object instance = constructor.newInstance(value);
                    if (value == null) {
                        trySetNonSerializableField(instance);
                    }
                    return instance;
                } catch (Exception | LinkageError ignored) {
                }
            }
        }

        for (Constructor<?> constructor : constructors) {
            if (constructor.getParameterCount() == 0) {
                try {
                    constructor.setAccessible(true);
                    Object instance = constructor.newInstance();
                    trySetNonSerializableField(instance);
                    return instance;
                } catch (Exception | LinkageError ignored) {
                }
            }
        }

        Object allocated = allocateInstance(serializableSerializerClass);
        if (allocated != null) {
            trySetNonSerializableField(allocated);
            return allocated;
        }

        return null;
    }

    private static void trySetNonSerializableField(Object instance) {
        Class<?> current = instance.getClass();
        while (current != null) {
            for (Field field : current.getDeclaredFields()) {
                if (Modifier.isStatic(field.getModifiers()) || Modifier.isTransient(field.getModifiers())) {
                    continue;
                }

                Object value = createNonSerializableValue(field.getType());
                if (value == null && !Serializable.class.isAssignableFrom(field.getType())) {
                    value = new Object();
                }

                if (value != null) {
                    try {
                        field.setAccessible(true);
                        field.set(instance, value);
                        return;
                    } catch (Exception | LinkageError ignored) {
                    }
                }
            }
            current = current.getSuperclass();
        }
    }

    private static Object createNonSerializableValue(Class<?> type) {
        if (type == null || type.isPrimitive()) {
            return null;
        }

        if (!Modifier.isAbstract(type.getModifiers()) && !type.isInterface()) {
            try {
                Constructor<?> constructor = type.getDeclaredConstructor();
                constructor.setAccessible(true);
                Object candidate = constructor.newInstance();
                if (type.isInstance(candidate) && !(candidate instanceof Serializable)) {
                    return candidate;
                }
            } catch (Exception | LinkageError ignored) {
            }

            Object allocated = allocateInstance(type);
            if (allocated != null && type.isInstance(allocated) && !(allocated instanceof Serializable)) {
                return allocated;
            }
        }

        String packageName = type.getPackage() == null ? "" : type.getPackage().getName();
        String prefix = packageName.isEmpty() ? "" : packageName + ".";

        String[] simpleNames = {
                "StringSerializer",
                "IntegerSerializer",
                "LongSerializer",
                "DoubleSerializer",
