 * @throws IllegalArgumentException
 * 		if the rawValue cannot be converted in the specified target
 * 		type clazz
 */
@SuppressWarnings("unchecked")
public static <T> T convertValue(Object rawValue, Class<?> clazz) {
    if (Integer.class.equals(clazz)) {
        return ((T) (convertToInt(rawValue)));
    } else if (Long.class.equals(clazz)) {
        return ((T) (convertToLong(rawValue)));
    } else if (Boolean.class.equals(clazz)) {
        return ((T) (convertToBoolean(rawValue)));
    } else if (Float.class.equals(clazz)) {
        return ((T) (convertToFloat(rawValue)));
    } else if (Double.class.equals(clazz)) {
        return ((T) (convertToDouble(rawValue)));
    } else if (String.class.equals(clazz)) {
        // PATH: Test should invoke the next ConfigurationUtils.convertToString(...) [step in execution path]
        return ((T) (convertToString(rawValue)));
    } else if (clazz.isEnum()) {
        return ((T) (convertToEnum(rawValue, ((Class<? extends Enum<?>>) (clazz)))));
    } else if (clazz == Duration.class) {
        return ((T) (convertToDuration(rawValue)));
    } else if (clazz == MemorySize.class) {
        return ((T) (convertToMemorySize(rawValue)));
    } else if (clazz == Map.class) {
        return ((T) (convertToProperties(rawValue)));
    }
    throw new IllegalArgumentException("Unsupported type: " + clazz);
}

static String convertToString(Object o) {
